import { Component, HostListener, Input, OnInit } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { IProductImageModel } from 'src/app/data/model/product/AddOrUpdateProductModel';

@Component({
  selector: 'app-admin-product-photo-gallery-modal-page',
  templateUrl: './admin-product-photo-gallery-modal-page.component.html',
  styleUrls: ['./admin-product-photo-gallery-modal-page.component.scss']
})
export class AdminProductPhotoGalleryModalPageComponent implements OnInit {

  photo = '';
  index = 1;
  @Input() gallery: IProductImageModel[] = [];

  constructor(public modalController: ModalController) { }

  @HostListener('window:popstate', ['$event'])
  onPopState(event) {
    this.modalController.dismiss();
  }

  ngOnInit(): void {

    this.photo = this.gallery[0].url;
  }

  dismiss(data?: any) {

    if (data != null) {

      this.modalController.dismiss({ code: data, id: this.gallery[this.index - 1].id });
    } else {

      this.modalController.dismiss();
    }
  }

  next() {

    if (this.index < this.gallery.length) {

      this.photo = this.gallery[this.index].url;
      this.index++;
    }
  }

  back() {

    if (this.index > 1) {

      this.index--;
      this.photo = this.gallery[this.index - 1].url;
    }
  }
}
