import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { ProductImageStateComponent } from './product-image-state.component';

const routes: Routes = [{ path: '', component: ProductImageStateComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ProductImageStateRoutingModule { }
